// Validate incoming payload. Required: business_name, business_url, business_sector.
const input = $input.first().json.body || $input.first().json;

const required = ['business_name', 'business_url', 'business_sector'];
const missing = required.filter(k => !input[k]);
if (missing.length) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Auth check — webhook protected by shared secret in header
const headers = $input.first().json.headers || {};
const providedSecret = headers['x-webhook-secret'];
if (providedSecret !== $vars.WEBHOOK_SECRET) {
  throw new Error('Unauthorized — bad webhook secret');
}

return [{
  json: {
    business_name: String(input.business_name).trim(),
    business_url: String(input.business_url).trim(),
    business_sector: String(input.business_sector).trim().toLowerCase(),
    instagram_handle: input.instagram_handle || null,
    contact_email: input.contact_email || null,
    contact_name: input.contact_name || null,
    source: input.source || 'manual'
  }
}];

// Supabase returns an array even on single-row upsert.
const rows = $input.first().json;
const row = Array.isArray(rows) ? rows[0] : rows;
if (!row || !row.id) {
  throw new Error('Failed to upsert lead — empty Supabase response');
}

// Pass everything forward; downstream nodes need the lead_id.
return [{
  json: {
    lead_id: row.id,
    business_name: row.business_name,
    business_url: row.business_url,
    business_sector: row.business_sector,
    instagram_handle: row.instagram_handle
  }
}];

// Strip HTML to readable text. Truncate to ~6000 chars to control token cost.
// Inject a fallback if scrape failed (anti-bot, 403, timeout).

const lead = $('Extract lead_id').first().json;
const scrapeOutput = $input.first().json;
let rawHtml = '';

if (typeof scrapeOutput === 'string') {
  rawHtml = scrapeOutput;
} else if (scrapeOutput && scrapeOutput.data) {
  rawHtml = String(scrapeOutput.data);
} else if (scrapeOutput && scrapeOutput.body) {
  rawHtml = String(scrapeOutput.body);
}

const scrapeFailed = !rawHtml || rawHtml.length < 200;

let cleaned;
if (scrapeFailed) {
  cleaned = `[NO_CONTENT_AVAILABLE — fallback mode]\nBusiness: ${lead.business_name}\nSector: ${lead.business_sector}\nURL: ${lead.business_url}\n\nDiagnose using sector-typical pain points only.`;
} else {
  cleaned = rawHtml
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);
}

return [{
  json: {
    lead_id: lead.lead_id,
    business_name: lead.business_name,
    business_url: lead.business_url,
    business_sector: lead.business_sector,
    scrape_failed: scrapeFailed,
    raw_html_snippet: cleaned.slice(0, 2000),
    cleaned_content: cleaned
  }
}];

// Parse Claude response. Validate structure. Throw on malformed JSON
// (caught by Error trigger workflow → quarantine the lead).

const response = $input.first().json;
const clean = $('Clean & truncate HTML').first().json;

let text = '';
try {
  text = response.content[0].text;
} catch (e) {
  throw new Error('Claude response missing content[0].text: ' + JSON.stringify(response).slice(0, 500));
}

// Strip stray markdown fences if Claude slips them in.
text = text.trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Claude returned non-JSON: ' + text.slice(0, 500));
}

const required = ['tasks', 'total_hours_lost_weekly', 'total_cost_annual', 'pitch_hook'];
for (const k of required) {
  if (!(k in parsed)) throw new Error(`Missing key in Claude response: ${k}`);
}
if (!Array.isArray(parsed.tasks) || parsed.tasks.length !== 3) {
  throw new Error('Expected exactly 3 tasks, got ' + (parsed.tasks?.length ?? 'none'));
}

// Compute usage cost for logging (Sonnet 4 published rates).
const usage = response.usage || {};
const inTok = usage.input_tokens || 0;
const outTok = usage.output_tokens || 0;
const costUsd = (inTok / 1e6) * 3 + (outTok / 1e6) * 15;

return [{
  json: {
    lead_id: clean.lead_id,
    business_name: clean.business_name,
    raw_html_snippet: clean.raw_html_snippet,
    raw_response: parsed,
    total_hours_lost_weekly: parsed.total_hours_lost_weekly,
    total_cost_annual: parsed.total_cost_annual,
    pitch_hook: parsed.pitch_hook,
    confidence: parsed.confidence ?? 0.5,
    tokens_in: inTok,
    tokens_out: outTok,
    api_cost_usd: Number(costUsd.toFixed(4))
  }
}];

